(()=>{'use strict';const A=[...document.querySelectorAll('.exercise')],T=[...document.querySelectorAll('textarea[data-id]')],B=document.querySelector('#progressBar'),K='sintesis-v2',w=(m,e)=>console.warn('[sintesis] '+m,e||''),get=()=>{try{return JSON.parse(localStorage.getItem(K)||'{}')}catch(e){w('storage',e);return{}}},save=()=>{try{localStorage.setItem(K,JSON.stringify({d:A.filter(x=>x.querySelector('[data-check]')?.checked).map(x=>x.id),t:Object.fromEntries(T.map(x=>[x.dataset.id,x.value]))}))}catch(e){w('storage',e)}},draw=()=>{let n=A.filter(x=>x.querySelector('[data-check]')?.checked).length,p=Math.min(100,Math.round(n/8*100));if(B)B.style.width=p+'%',B.textContent=p+'%',B.setAttribute('aria-valuenow',p)};let d=get();A.forEach(x=>{let c=x.querySelector('[data-check]');if(c)c.checked=(d.d||[]).includes(x.id)});T.forEach(x=>x.value=d.t?.[x.dataset.id]||x.value.trim());document.addEventListener('input',e=>{if(e.target.matches('textarea[data-id]'))save()});document.addEventListener('change',e=>{if(e.target.matches('[data-check]'))save(),draw()});document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action;if(a==='print')print();else if(a==='reset'){try{localStorage.removeItem(K)}catch(e){w('storage',e)}location.reload()}else if(a==='download'){let u=URL.createObjectURL(new Blob([JSON.stringify(get(),null,2)],{type:'application/json'})),x=document.createElement('a');x.href=u;x.download='progreso-sintesis-aditiva.json';x.click();setTimeout(()=>URL.revokeObjectURL(u),0)}});addEventListener('error',e=>w('error',e.error||e.message));addEventListener('unhandledrejection',e=>w('rejection',e.reason));draw();if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sintesis-sw.js').catch(e=>w('cache',e)),{once:true})})();